/* СИБИРЯК · партнёры, деньги, документы, настройки, старт (sibiryak-app2.js) */
function mDirectory(){const st=vs('directory');let ps=rows('u_partners').filter(p=>p.status==='verified');if(st.q)ps=ps.filter(p=>(p.name+' '+p.about+' '+(p.services||[]).map(s=>s.title).join(' ')).toLowerCase().includes(st.q.toLowerCase()));if(st.f!=='all')ps=ps.filter(p=>p.category===st.f);ps=[...ps].sort((a,b)=>st.sort==='price'?Math.min(...a.services.map(s=>+s.price||0))-Math.min(...b.services.map(s=>+s.price||0)):st.sort==='rating'?pRating(b)-pRating(a):(b.plan==='pro')-(a.plan==='pro'));return `<div class="hero reveal"><h1>🤝 <em>Проверенные партнёры</em> для всех</h1><p>Медицина, образование, право, финансы, ремонт, ЖКХ и любые услуги. Каждый партнёр прошёл проверку ИНН, ОГРН и лицензий.</p></div><div class="card"><div class="row" style="margin-top:0"><input class="input" style="flex:2;margin:0" placeholder="🔍 Поиск по названию и услугам" value="${esc(st.q)}" oninput="vs('directory').q=this.value;vsSet('directory',vs('directory'));render()"><select class="input" style="flex:1;margin:0" onchange="vs('directory').sort=this.value;vsSet('directory',vs('directory'));render()"><option value="pro">Сначала PRO</option><option value="rating" ${st.sort==='rating'?'selected':''}>По рейтингу</option><option value="price" ${st.sort==='price'?'selected':''}>По цене</option></select></div><div class="chips" style="margin-top:8px"><button class="chip ${st.f==='all'?'on':''}" onclick="vs('directory').f='all';vsSet('directory',vs('directory'));render()">Все</button>${PCATS.map(c=>`<button class="chip ${st.f===c.id?'on':''}" onclick="vs('directory').f='${c.id}';vsSet('directory',vs('directory'));render()">${c.icon} ${esc(c.name)}</button>`).join('')}</div>${viewsBarHtml('directory')}</div>${ps.map(p=>`<div class="item reveal" style="cursor:pointer" onclick="partnerDrawer('${p.id}')"><div class="t">${pcat(p.category).icon} ${esc(p.name)} ${p.plan==='pro'?'<span class="pill p-warn">PRO</span>':''} <span class="pill p-ok">проверен</span></div><div class="s">${esc(pcat(p.category).name)} · ${esc(p.city)} · ★ ${pRating(p).toFixed(1)} · от ${money(Math.min(...p.services.map(s=>+s.price||0)))}</div><div class="s">${esc(p.about).slice(0,100)}</div></div>`).join('')||'<div class="empty">Проверенных партнёров пока нет.</div>'}`}
function partnerDrawer(id){const p=find('u_partners',id);if(!p)return;const rv=rows('u_reviews').filter(r=>r.target_id===id);openDrawer(`<h3>${pcat(p.category).icon} ${esc(p.name)}</h3><div class="row" style="margin-top:0"><span class="pill p-ok">проверен</span>${p.plan==='pro'?'<span class="pill p-warn">PRO</span>':''}<span class="pill p-dim">${esc(p.org)}</span></div><div class="note">${esc(p.city)} · ИНН ${esc(p.inn)} · ${p.license?esc(p.license):'лицензия не требуется'}</div><p style="margin:10px 0;font-size:13px;color:var(--dim)">${esc(p.about)}</p><h3>Услуги и цены</h3>${(p.services||[]).map(s=>`<div class="item"><div class="row" style="margin:0"><div style="flex:1"><div class="t" style="font-size:13px">${esc(s.title)}</div><div class="s">за ${esc(s.unit)}</div></div><b style="color:var(--pine)">${+s.price?money(+s.price):'бесплатно'}</b><button class="btn sm pri" onclick="leadForm('${p.id}','${esc(s.title)}',${+s.price||0})">Заказать</button></div></div>`).join('')}<div class="row"><button class="btn sm gh" onclick="location.href='tel:${esc(p.phone.replace(/[^\d+]/g,''))}'">📞 ${esc(p.phone)}</button>${p.site?`<button class="btn sm gh" onclick="window.open('https://${esc(p.site)}','_blank')">🌐 Сайт</button>`:''}</div><h3 style="margin-top:12px">Документы</h3>${(p.docs||[]).map(d=>`<div class="ev">📎 ${d.url?`<a href="${esc(d.url)}" target="_blank">${esc(d.name)}</a>`:esc(d.name)}</div>`).join('')||'<div class="note">Нет документов.</div>'}<h3 style="margin-top:12px">Отзывы (${rv.length})</h3>${rv.map(r=>`<div class="ev">${'★'.repeat(r.stars)} ${esc(r.text)}</div>`).join('')||'<div class="note">Отзывов нет.</div>'}`)}
let ptWiz=null;
function mPtReg(){const me=mine('u_partners')[0];if(me&&me.status!=='draft')return `<div class="card"><h3>${ic('hand')} Вы уже партнёр</h3><div class="note">Статус: ${me.status}. Управление — в кабинете партнёра.</div><div class="row"><button class="btn pri" onclick="openModule('ptcab')">Открыть кабинет</button></div></div>`;return `<div class="hero reveal"><h1>🤝 <em>Стать партнёром</em> платформы</h1><p>Для компаний, оказывающих медицинские, образовательные, юридические и любые сервисные услуги. Проверенный бейдж, заявки клиентов, место в каталоге. Платформа работает для всех.</p><div class="chips">${PCATS.map(c=>`<span class="chip">${c.icon} ${esc(c.name)}</span>`).join('')}</div></div><div class="card"><div class="row"><button class="btn pri" onclick="ptWizard()">Начать регистрацию →</button></div></div>`}
function ptWizard(edit){const me=mine('u_partners')[0];ptWiz={step:1,data:edit&&me?JSON.parse(JSON.stringify(me)):{category:'med',org:'ООО',name:G.profile.company_name||meName(),inn:'',ogrn:'',license:'',city:G.profile.city,radius:60,phone:G.profile.phone||'',site:'',about:'',consent:false,docs:[],services:[{id:uid(),title:'',price:'',unit:'услуга'}]}};ptWizRender()}
function ptWizRender(){const d=ptWiz.data,s=ptWiz.step,c=pcat(d.category);let body='';if(s===1)body=`<label class="lbl">Категория</label><select class="input" id="pw-cat">${PCATS.map(x=>`<option value="${x.id}" ${d.category===x.id?'selected':''}>${x.icon} ${esc(x.name)}</option>`).join('')}</select><label class="lbl">Организационная форма</label><select class="input" id="pw-org">${['ООО','ИП','Самозанятый','НКО','АО'].map(o=>`<option ${d.org===o?'selected':''}>${o}</option>`).join('')}</select><label class="lbl">Название</label><input class="input" id="pw-name" value="${esc(d.name)}"><label class="lbl">Город</label><input class="input" id="pw-city" value="${esc(d.city)}"><label class="lbl">О компании</label><textarea class="input" id="pw-about" rows="3">${esc(d.about)}</textarea>`;if(s===2)body=`<label class="lbl">ИНН (контрольная сумма ФНС)</label><input class="input" id="pw-inn" value="${esc(d.inn)}" oninput="innHint(this.value)"><div class="note" id="inn-h"></div><label class="lbl">ОГРН / ОГРНИП</label><input class="input" id="pw-ogrn" value="${esc(d.ogrn)}">${c.lic?`<label class="lbl">${esc(c.lic)}</label><input class="input" id="pw-lic" value="${esc(d.license)}">`:''}<label class="lbl">Телефон</label><input class="input" id="pw-phone" value="${esc(d.phone)}"><label class="lbl">Сайт</label><input class="input" id="pw-site" value="${esc(d.site)}"><label class="lbl">Документы (лицензия, сертификат)</label><input class="input" type="file" id="pw-doc" accept=".pdf,.jpg,.png" onchange="ptDoc(this)"><div class="chips">${d.docs.map((x,i)=>`<span class="chip">📎 ${esc(x.name)} <b style="cursor:pointer" onclick="ptWiz.data.docs.splice(${i},1);ptWizRender()">✕</b></span>`).join('')||'<span class="note">Файлы не загружены</span>'}</div>`;if(s===3)body=`<label class="lbl">Прайс услуг</label>${d.services.map((x,i)=>`<div class="row" style="margin-top:0"><input class="input" style="flex:2;margin:0" value="${esc(x.title)}" placeholder="Услуга" oninput="ptWiz.data.services[${i}].title=this.value"><input class="input" style="flex:1;margin:0" type="number" value="${esc(x.price)}" placeholder="₽" oninput="ptWiz.data.services[${i}].price=this.value"><button class="btn sm dgr" onclick="ptWiz.data.services.splice(${i},1);ptWizRender()">✕</button></div>`).join('')}<div class="row"><button class="btn sm gh" onclick="ptWiz.data.services.push({id:uid(),title:'',price:'',unit:'услуга'});ptWizRender()">＋ Услуга</button></div><label class="lbl" style="text-transform:none;letter-spacing:0;margin-top:10px"><input type="checkbox" class="cb" id="pw-consent" ${d.consent?'checked':''}> Согласие на обработку данных по 152-ФЗ и достоверность реквизитов</label>`;openDrawer(`<h3>Регистрация партнёра · шаг ${s}/3</h3>${body}<div class="row">${s>1?`<button class="btn gh" onclick="ptCollect();ptWiz.step--;ptWizRender()">← Назад</button>`:''}${s<3?`<button class="btn pri" onclick="ptCollect();ptNext()">Далее →</button>`:`<button class="btn pri" onclick="ptCollect();ptSubmit()">📤 На проверку</button>`}</div>`);if(s===2)innHint(d.inn)}
function innHint(v){const e=$('inn-h');if(!e)return;const s=String(v).replace(/\D/g,'');e.innerHTML=s?(innValid(s)?'<span style="color:var(--pine)">✓ сумма верна</span>':'<span style="color:var(--rose)">✗ сумма не сходится</span>'):''}
function ptCollect(){const d=ptWiz.data,g=val;if(ptWiz.step===1){d.category=g('pw-cat')||d.category;d.org=g('pw-org')||d.org;d.name=g('pw-name');d.city=g('pw-city');d.about=g('pw-about')}if(ptWiz.step===2){d.inn=g('pw-inn');d.ogrn=g('pw-ogrn');d.license=g('pw-lic');d.phone=g('pw-phone');d.site=g('pw-site')}if(ptWiz.step===3){const c=$('pw-consent');d.consent=c?c.checked:false}}
function ptNext(){const d=ptWiz.data;if(ptWiz.step===1&&!d.name){toast('Укажите название',true);return}if(ptWiz.step===2&&!innValid(d.inn)){toast('ИНН не проходит проверку',true);return}ptWiz.step++;ptWizRender()}
async function ptDoc(input){const f=input.files[0];if(!f)return;const url=await SBup('partners/'+meId()+'/'+Date.now()+'_'+f.name,f);ptWiz.data.docs.push(url?{name:f.name,url}:{name:f.name,local:true});ptWizRender();toast(url?'Документ загружен в хранилище':'Документ прикреплён локально')}
function ptSubmit(){const d=ptWiz.data;if(!d.consent){toast('Нужно согласие',true);return}d.services=d.services.filter(s=>s.title).map(s=>({...s,price:+s.price||0}));if(!d.services.length){toast('Добавьте услугу',true);return}const me=mine('u_partners')[0];const rec=Object.assign(me||{id:uid(),owner_id:meId(),created_at:now()},d,{status:'checking',plan:me?me.plan:'free',sort:me?me.sort:rows('u_partners').length});putRec('u_partners',rec);closeDrawer();openModule('ptcab');toast('Отправлено на проверку');setTimeout(()=>{const p=find('u_partners',rec.id);if(!p||p.status!=='checking')return;const bad=pChecks(p).filter(c=>!c.ok);p.status=bad.length?'rejected':'verified';p.reject=bad.map(b=>b.t);mirror();render();persist('u_partners',{id:p.id,status:p.status,reject:p.reject},'upd').catch(()=>{});notify(meId(),'Партнёр «'+p.name+'»: '+(p.status==='verified'?'проверен и опубликован':'отклонён — '+bad[0].t))},2600)}
function mPtCab(){const me=mine('u_partners')[0];if(!me)return `<div class="card"><h3>${ic('shield')} Кабинет партнёра</h3><div class="empty">Вы ещё не партнёр.</div><div class="row"><button class="btn pri" onclick="openModule('ptreg')">Зарегистрироваться</button></div></div>`;const checks=pChecks(me),sc=pScore(me);const leads=rows('u_leads').filter(l=>l.partner_id===me.id);const rev=leads.filter(l=>l.status==='done').reduce((a,l)=>a+l.budget,0);const st={draft:['Черновик','p-dim'],checking:['На проверке','p-wait'],verified:['Проверен','p-ok'],rejected:['Отклонён','p-bad']}[me.status];return `<div class="hero reveal"><h1>${pcat(me.category).icon} ${esc(me.name)}</h1><div class="row" style="margin-top:6px"><span class="pill ${st[1]}">${st[0]}</span>${me.plan==='pro'?'<span class="pill p-warn">PRO</span>':'<span class="pill p-dim">FREE</span>'}<span class="pill p-ice">★ ${pRating(me).toFixed(1)}</span></div><div class="prog"><i style="width:${sc}%"></i></div><div class="note">Готовность к проверке: ${sc}%</div>${me.status==='rejected'?`<div class="banner">Причины: ${esc((me.reject||[]).join('; '))}<button class="btn sm warn" onclick="ptWizard(true)">Исправить</button></div>`:''}${me.status==='draft'?`<div class="row"><button class="btn pri" onclick="ptWizard(true)">Завершить регистрацию →</button></div>`:''}</div><div class="card"><h3>Проверка платформы</h3>${checks.map(c=>`<div class="ev"><span style="color:${c.ok?'var(--pine)':'var(--rose)'}">${c.ok?'✓':'✗'}</span> ${esc(c.t)}</div>`).join('')}</div><div class="kpis"><div class="kpi"><b>${leads.filter(l=>l.status==='new').length}</b><span>НОВЫХ ЗАЯВОК</span></div><div class="kpi"><b>${leads.filter(l=>l.status==='accepted').length}</b><span>В РАБОТЕ</span></div><div class="kpi"><b>${money(rev)}</b><span>ВЫРУЧКА</span></div></div><div class="card"><h3>Тариф</h3><div class="row"><div class="item" style="flex:1;${me.plan==='free'?'border-color:var(--ice2)':''}"><div class="t">Free · 0 ₽</div><div class="s">Каталог, заявки, чат, проверка.</div><button class="btn sm gh" onclick="putRec('u_partners',{id:'${me.id}',plan:'free'})">Выбрать</button></div><div class="item" style="flex:1;${me.plan==='pro'?'border-color:var(--amber)':''}"><div class="t">PRO · 4 900 ₽/мес</div><div class="s">Приоритет в каталоге, бейдж, поднятие в поиске.</div><button class="btn sm warn" onclick="putRec('u_partners',{id:'${me.id}',plan:'pro'})">Выбрать</button></div></div></div>${listView('psvc',{table:'u_partners',ph:'Поиск услуги',add:'psvcForm()',empty:'Услуг нет.',rows:()=>(me.services||[]).map((s,i)=>({...s,_i:i,sort:i})),search:r=>r.title,sorts:{def:(a,b)=>a._i-b._i,price:(a,b)=>(+a.price||0)-(+b.price||0)},sortNames:{def:'Мой порядок',price:'По цене'},row:(r,i)=>`<div class="item" ${dragAttrs('psvc',i)}><div class="row" style="margin:0"><div style="flex:1"><div class="t" style="font-size:13px">${esc(r.title)}</div><div class="s">за ${esc(r.unit)}</div></div><b style="color:var(--pine)">${money(+r.price||0)}</b><button class="btn sm gh" onclick="psvcForm(${r._i})">✏️</button><button class="btn sm dgr" onclick="psvcDel(${r._i})">🗑</button></div></div>`})}<div class="card"><h3>Документы</h3>${(me.docs||[]).map(d=>`<div class="ev">📎 ${d.url?`<a href="${esc(d.url)}" target="_blank">${esc(d.name)}</a>`:esc(d.name)+(d.local?' (локально)':'')}</div>`).join('')||'<div class="note">Нет документов.</div>'}<div class="row"><button class="btn sm gh" onclick="ptWizard(true)">Загрузить</button><button class="btn sm gh" onclick="partnerDrawer('${me.id}')">Публичная страница</button></div></div>`}
function psvcForm(i){const me=mine('u_partners')[0];const s=i!=null?me.services[i]:null;openDrawer(`<h3>${s?'Редактирование услуги':'Новая услуга'}</h3><label class="lbl">Название</label><input class="input" id="ps-t" value="${esc(s?s.title:'')}"><div class="row"><input class="input" style="flex:1" id="ps-p" type="number" value="${s?s.price:''}" placeholder="₽"><input class="input" style="flex:1" id="ps-u" value="${esc(s?s.unit:'услуга')}"></div><div class="row"><button class="btn pri" onclick="psvcSave(${i!=null?i:-1})">💾</button></div>`)}
function psvcSave(i){const me=mine('u_partners')[0];if(!val('ps-t')){toast('Название услуги',true);return}const rec={id:i>=0?me.services[i].id:uid(),title:val('ps-t'),price:num('ps-p'),unit:val('ps-u')||'услуга'};const sv=[...(me.services||[])];if(i>=0)sv[i]=rec;else sv.push(rec);putRec('u_partners',{id:me.id,services:sv});closeDrawer();toast('Услуга сохранена')}
function psvcDel(i){const me=mine('u_partners')[0];const sv=[...me.services];const rec=sv[i];sv.splice(i,1);putRec('u_partners',{id:me.id,services:sv});snack('Услуга удалена','Вернуть',()=>{const m=mine('u_partners')[0];const s2=[...m.services];s2.splice(i,0,rec);putRec('u_partners',{id:m.id,services:s2})})}
function leadForm(pid,service,price){openDrawer(`<h3>Заявка партнёру</h3><label class="lbl">Услуга</label><input class="input" id="ld-s" value="${esc(service)}"><label class="lbl">Имя</label><input class="input" id="ld-n" value="${esc(meName())}"><label class="lbl">Телефон</label><input class="input" id="ld-p" value="${esc(G.profile.phone||'')}"><label class="lbl">Бюджет, ₽</label><input class="input" id="ld-b" type="number" value="${price||0}"><label class="lbl">Комментарий</label><textarea class="input" id="ld-c" rows="3"></textarea><div class="row"><button class="btn pri" onclick="leadSend('${pid}')">📨 Отправить</button></div>`)}
function leadSend(pid){if(!val('ld-n')||!val('ld-p')){toast('Имя и телефон',true);return}const l={id:uid(),partner_id:pid,owner_id:meId(),service:val('ld-s'),client:val('ld-n'),phone:val('ld-p'),budget:num('ld-b'),comment:val('ld-c'),status:'new',msgs:[],created_at:now()};G.cache.u_leads.unshift(l);mirror();render();persist('u_leads',l,'ins').catch(()=>{});const p=find('u_partners',pid);notify(p.owner_id,'Новая заявка: '+l.service);closeDrawer();toast('Заявка отправлена партнёру')}
function mLeads(){const me=mine('u_partners')[0];if(!me)return '<div class="empty">Сначала зарегистрируйтесь как партнёр.</div>';return listView('leads',{table:'u_leads',ph:'Поиск по клиенту',empty:'Заявок клиентов нет.',rows:()=>rows('u_leads').filter(l=>l.partner_id===me.id),search:r=>r.client+' '+r.service,filters:[{v:'new',t:'Новые',fn:r=>r.status==='new'},{v:'accepted',t:'Принятые',fn:r=>r.status==='accepted'},{v:'done',t:'Выполненные',fn:r=>r.status==='done'}],sorts:{def:(a,b)=>String(b.created_at).localeCompare(String(a.created_at)),budget:(a,b)=>b.budget-a.budget},sortNames:{def:'Сначала новые',budget:'По бюджету'},row:r=>`<div class="item" style="cursor:pointer" onclick="leadDrawer('${r.id}')"><div class="row" style="margin:0">${cbHtml('leads',r.id)}<div style="flex:1"><div class="t">${esc(r.service)}</div><div class="s">${esc(r.client)} · ${esc(r.phone)} · ${money(r.budget)}</div></div><span class="pill ${r.status==='new'?'p-wait':r.status==='done'?'p-ok':'p-ice'}">${{new:'новая',accepted:'принята',done:'выполнена',declined:'отклонена'}[r.status]||r.status}</span></div></div>`})}
function leadDrawer(id){const l=find('u_leads',id);if(!l)return;const acts=[];if(l.status==='new')acts.push(`<button class="btn sm pri" onclick="leadSet('${id}','accepted')">✅ Принять</button>`,`<button class="btn sm dgr" onclick="leadSet('${id}','declined')">Отклонить</button>`);if(l.status==='accepted')acts.push(`<button class="btn sm pri" onclick="leadSet('${id}','done')">🏁 Выполнено</button>`);acts.push(`<button class="btn sm gh" onclick="location.href='tel:${esc(l.phone.replace(/[^\d+]/g,''))}'">📞</button>`,`<button class="btn sm dgr" onclick="delRec('u_leads','${id}')">🗑</button>`);openDrawer(`<h3>${esc(l.service)}</h3><div class="note">${esc(l.client)} · ${esc(l.phone)} · ${money(l.budget)}</div><p style="margin:8px 0;font-size:13px;color:var(--dim)">${esc(l.comment)}</p><div class="row">${acts.join('')}</div><h3 style="margin-top:12px">Чат с клиентом</h3><div class="msgs" id="lchat">${(l.msgs||[]).map(m=>`<div class="msg ${m.from==='partner'?'me':'them'}">${esc(m.text)}<small>${esc(m.time)}</small></div>`).join('')||'<div class="note">Сообщений нет.</div>'}</div><div class="row"><input class="input" style="flex:1;margin:0" id="l-in" placeholder="Сообщение…"><button class="btn sm pri" onclick="leadMsg('${id}')">➤</button></div>`)}
function leadSet(id,st){const l=find('u_leads',id);l.status=st;mirror();render();persist('u_leads',{id,status:st},'upd').catch(()=>{});notify(l.owner_id,'Заявка «'+l.service+'»: '+st);closeDrawer();toast('Статус обновлён')}
function leadMsg(id){const l=find('u_leads',id);const t=val('l-in');if(!t)return;l.msgs=l.msgs||[];l.msgs.push({from:'partner',text:t,time:hm()});mirror();persist('u_leads',{id,msgs:l.msgs},'upd').catch(()=>{});leadDrawer(id)}
function mMod(){const q=rows('u_partners').filter(p=>p.status==='checking'||p.status==='rejected');const disputes=rows('u_deals').filter(d=>d.status==='dispute');return `<div class="card"><h3>${ic('shield')} Модерация</h3><div class="row" style="margin-top:0"><button class="btn sm ${G.mod?'pri':'gh'}" onclick="G.mod=!G.mod;render()">${G.mod?'🛡 Режим модератора: ВКЛ':'Включить режим модератора'}</button></div><div class="note">Демо-доступ для проверки процессов и решений. В продакшене — только команда платформы.</div></div>${!G.mod?'<div class="empty">Включите режим модератора.</div>':`${q.map(p=>`<div class="item"><div class="t">${pcat(p.category).icon} ${esc(p.name)} <span class="pill ${p.status==='checking'?'p-wait':'p-bad'}">${p.status==='checking'?'на проверке':'отклонён'}</span></div><div class="s">ИНН ${esc(p.inn)} · готовность ${pScore(p)}%</div>${pChecks(p).map(c=>`<div class="ev"><span style="color:${c.ok?'var(--pine)':'var(--rose)'}">${c.ok?'✓':'✗'}</span> ${esc(c.t)}</div>`).join('')}<div class="row"><button class="btn sm pri" onclick="modSet('${p.id}','verified')">✅ Одобрить</button><button class="btn sm dgr" onclick="modReject('${p.id}')">Отклонить</button><button class="btn sm gh" onclick="partnerDrawer('${p.id}')">Карточка</button></div></div>`).join('')||'<div class="empty">Очередь партнёров пуста.</div>'}<h3 style="margin:12px 0 8px">Споры по сделкам</h3>${disputes.map(d=>`<div class="item"><div class="t">${esc(d.title)}</div><div class="s">${esc(d.worker_name)} ↔ ${esc(d.employer_name)} · ${money(d.rate)}</div><div class="row"><button class="btn sm gh" onclick="complaint('${d.id}')">📄 Претензия</button><button class="btn sm pri" onclick="dealSet('${d.id}','closed','Спор закрыт модератором')">Закрыть</button></div></div>`).join('')||'<div class="empty">Споров нет.</div>'}`}`}
function modSet(id,st){const p=find('u_partners',id);const prev=p.status;p.status=st;p.reject=[];mirror();render();persist('u_partners',{id,status:st,reject:[]},'upd').catch(()=>{});notify(p.owner_id,'Партнёр «'+p.name+'»: '+st);snack('Решение применено','Отменить',()=>{p.status=prev;mirror();render();persist('u_partners',{id,status:prev},'upd').catch(()=>{})})}
function modReject(id){const r=prompt('Причина отклонения:','Не подтверждена лицензия');if(r===null)return;const p=find('u_partners',id);p.status='rejected';p.reject=[r];mirror();render();persist('u_partners',{id,status:'rejected',reject:[r]},'upd').catch(()=>{});notify(p.owner_id,'Партнёр отклонён: '+r)}
function mFinance(){const inc=mine('u_incomes');const byCat={};inc.forEach(i=>byCat[i.cat]=(byCat[i.cat]||0)+i.amount);const days={};for(let d=13;d>=0;d--)days[dAgo(d)]=0;inc.forEach(i=>{if(days[i.date]!=null)days[i.date]+=i.amount});const cols=['var(--ice)','var(--pine)','var(--amber)','var(--magenta)','var(--info)','var(--rose)'];const max=Math.max(...Object.values(days),1);const bars=Object.entries(days).map(([d,v],i)=>`<g><rect x="${i*24+6}" y="${120-v/max*100}" width="16" height="${v/max*100}" rx="4" fill="${cols[i%6]}" opacity=".9"/><text x="${i*24+14}" y="134" font-size="7" fill="var(--faint)" text-anchor="middle">${d.slice(8)}</text><text x="${i*24+14}" y="${116-v/max*100}" font-size="7" fill="var(--dim)" text-anchor="middle">${v?Math.round(v/100)/10+'k':''}</text></g>`).join('');const legend=Object.entries(byCat).map(([c,v],i)=>`<span class="chip" style="border-color:${cols[i%6]};color:${cols[i%6]}">${esc(c)} · ${money(v)}</span>`).join('');return `<div class="card"><h3>${ic('money')} Финансы</h3><div class="kpis"><div class="kpi"><b>${money(inc.reduce((a,i)=>a+i.amount,0))}</b><span>ЗА 14 ДНЕЙ</span></div><div class="kpi"><b>${inc.length}</b><span>ПОСТУПЛЕНИЙ</span></div></div><svg class="chart" viewBox="0 0 340 140">${bars}</svg><div class="chips">${legend}</div><div class="row"><button class="btn sm pri" onclick="incForm()">＋ Поступление</button><button class="btn sm gh" onclick="exportCSV()">⬇️ CSV для ИФНС/1С</button></div></div>${listView('inc',{table:'u_incomes',ph:'Поиск поступления',add:'incForm()',empty:'Поступлений нет.',rows:()=>inc,search:r=>r.cat+' '+r.note,filters:[{v:'Смена',t:'Смены',fn:r=>r.cat==='Смена'},{v:'Чаевые',t:'Чаевые',fn:r=>r.cat==='Чаевые'},{v:'Подработка',t:'Подработка',fn:r=>r.cat==='Подработка'}],sorts:{def:(a,b)=>String(b.date).localeCompare(String(a.date)),amount:(a,b)=>b.amount-a.amount},sortNames:{def:'По дате',amount:'По сумме'},row:r=>`<div class="item"><div class="row" style="margin:0">${cbHtml('inc',r.id)}<div style="flex:1"><div class="t">${money(r.amount)} · ${esc(r.cat)}</div><div class="s">${fdate(r.date)} · ${esc(r.note)}</div></div><button class="btn sm gh" onclick="incForm('${r.id}')">✏️</button><button class="btn sm dgr" onclick="delRec('u_incomes','${r.id}')">🗑</button></div></div>`})}`}
function incForm(id){const r=id?find('u_incomes',id):null;openDrawer(`<h3>${r?'Редактирование':'Поступление'}</h3><label class="lbl">Дата</label><input class="input" id="in-d" type="date" value="${r?r.date:dAgo(0)}"><label class="lbl">Категория</label><select class="input" id="in-c">${['Смена','Чаевые','Подработка','Услуга','Продажа','Другое'].map(c=>`<option ${r&&r.cat===c?'selected':''}>${c}</option>`).join('')}</select><label class="lbl">Сумма, ₽</label><input class="input" id="in-a" type="number" value="${r?r.amount:''}"><label class="lbl">Заметка</label><input class="input" id="in-n" value="${esc(r?r.note:'')}"><div class="row"><button class="btn pri" onclick="incSave('${id||''}')">💾</button></div>`)}
function incSave(id){if(!num('in-a')){toast('Укажите сумму',true);return}putRec('u_incomes',{id:id||uid(),owner_id:meId(),date:val('in-d'),cat:val('in-c'),amount:num('in-a'),note:val('in-n'),created_at:id?find('u_incomes',id).created_at:now()});closeDrawer();toast('Сохранено')}
function exportCSV(){const inc=mine('u_incomes');const csv='дата;категория;сумма;заметка\n'+inc.map(i=>[i.date,i.cat,i.amount,(i.note||'').replace(/;/g,',')].join(';')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sibiryak-dohody.csv';a.click();toast('CSV скачан')}
function mFamily(){const f=mine('u_family')[0];if(!f)return '<div class="empty">Цель семьи не задана.</div>';const pct=clamp(f.saved/f.target*100,0,100);return `<div class="card"><h3>${ic('fam')} Семейный бюджет</h3><div class="t" style="font-size:15px">${esc(f.goal_title)}</div><div class="prog"><i style="width:${pct}%"></i></div><div class="note">${money(f.saved)} из ${money(f.target)} · ${Math.round(pct)}% · авто-откладка ${f.percent}% с закрытых сделок</div><label class="lbl">Процент откладывания: ${f.percent}%</label><input type="range" min="0" max="50" step="5" value="${f.percent}" style="width:100%;accent-color:var(--pine)" oninput="famSet('percent',+this.value)"><label class="lbl">Цель</label><input class="input" id="fm-t" value="${esc(f.goal_title)}"><label class="lbl">Сумма цели, ₽</label><input class="input" id="fm-g" type="number" value="${f.target}"><div class="row"><input class="input" style="flex:1;margin:0" id="fm-add" type="number" placeholder="Добавить вручную, ₽"><button class="btn sm gh" onclick="famAdd()">＋</button><button class="btn sm pri" onclick="famSave()">💾 Цель</button></div><h3 style="margin-top:12px">Семья</h3><div class="chips">${(f.members||[]).map((m,i)=>`<span class="chip on">${esc(m)} <b style="cursor:pointer" onclick="famMemDel(${i})">✕</b></span>`).join('')}</div><div class="row"><input class="input" style="flex:1;margin:0" id="fm-m" placeholder="Имя члена семьи"><button class="btn sm gh" onclick="famMemAdd()">＋</button></div></div>`}
function famSet(k,v){const f=mine('u_family')[0];f[k]=v;mirror();persist('u_family',{id:f.id,[k]:v},'upd').catch(()=>{});render()}
function famSave(){const f=mine('u_family')[0];f.goal_title=val('fm-t')||f.goal_title;f.target=num('fm-g')||f.target;mirror();render();persist('u_family',{id:f.id,goal_title:f.goal_title,target:f.target},'upd').catch(()=>{});toast('Цель сохранена')}
function famAdd(){const f=mine('u_family')[0];const v=num('fm-add');if(!v)return;f.saved+=v;mirror();render();persist('u_family',{id:f.id,saved:f.saved},'upd').catch(()=>{});toast('Добавлено '+money(v))}
function famMemAdd(){const f=mine('u_family')[0];const v=val('fm-m');if(!v)return;f.members=[...(f.members||[]),v];mirror();render();persist('u_family',{id:f.id,members:f.members},'upd').catch(()=>{})}
function famMemDel(i){const f=mine('u_family')[0];f.members.splice(i,1);mirror();render();persist('u_family',{id:f.id,members:f.members},'upd').catch(()=>{})}
const DOCTPL={'Трудовой договор':(p,o)=>`ТРУДОВОЙ ДОГОВОР № ${p.no}\nг. ${p.city} · ${p.date}\nРаботодатель: ${o.company_name||o.name}\nРаботник: ${p.person}\nДолжность: ${p.type}\nОплата: ${money(p.sum||0)} в месяц.\nРежим: по графику сменности. Испытательный срок: 3 месяца.\nПодписи сторон: ____________ / ____________`,'ГПХ':(p,o)=>`ДОГОВОР ГПХ № ${p.no}\nЗаказчик: ${o.company_name||o.name}\nИсполнитель: ${p.person}\nПредмет: ${p.type}\nВознаграждение: ${money(p.sum||0)} по акту.\nСрок: ${p.date} — по завершении.\nПодписи: ____________ / ____________`,'Акт':(p,o)=>`АКТ ВЫПОЛНЕННЫХ РАБОТ № ${p.no}\nЗаказчик: ${o.company_name||o.name}\nИсполнитель: ${p.person}\nРаботы: ${p.type}\nСумма: ${money(p.sum||0)}\nПретензий по объёму и срокам нет.\nПодписи: ____________ / ____________`,'Оферта НПД':(p,o)=>`ОФЕРТА САМОЗАНЯТОГО № ${p.no}\nИсполнитель: ${p.person} (НПД)\nЗаказчик: ${o.company_name||o.name}\nУслуга: ${p.type}\nСтоимость: ${money(p.sum||0)}\nЧек НПД формируется автоматически после оплаты.\nАкцепт: оплата счёта.`};
function mDocs(){return `<div class="card"><h3>${ic('doc')} Документы и КЭДО</h3><div class="note">Шаблоны рождаются из данных сделок и профиля. Подписание — кодом из SMS (демо ПЭП); в продакшене — УКЭП «Госключ».</div><div class="row"><button class="btn sm pri" onclick="docForm()">＋ Документ из шаблона</button></div></div>${listView('docs',{table:'u_documents',ph:'Поиск документа',add:'docForm()',empty:'Документов нет.',rows:()=>mine('u_documents'),search:r=>r.kind+' '+r.person+' '+r.no,filters:[{v:'Договор',t:'Договоры',fn:r=>r.kind==='Договор'},{v:'Акт',t:'Акты',fn:r=>r.kind==='Акт'}],sorts:{def:(a,b)=>String(b.date).localeCompare(String(a.date))},sortNames:{def:'По дате'},row:r=>`<div class="item"><div class="row" style="margin:0">${cbHtml('docs',r.id)}<div style="flex:1"><div class="t">${esc(r.kind)} · ${esc(r.type)} · № ${esc(r.no)}</div><div class="s">${esc(r.person)} · ${fdate(r.date)} · <span class="pill ${r.status==='Подписан'?'p-ok':'p-wait'}">${esc(r.status)}</span></div></div><button class="btn sm gh" onclick="docView('${r.id}')">👁</button>${r.status!=='Подписан'?`<button class="btn sm pri" onclick="docSign('${r.id}')">✍️ Подписать</button>`:''}<button class="btn sm dgr" onclick="delRec('u_documents','${r.id}')">🗑</button></div></div>`})}`}
function docForm(){openDrawer(`<h3>Документ из шаблона</h3><label class="lbl">Шаблон</label><select class="input" id="dc-k">${Object.keys(DOCTPL).map(k=>`<option>${k}</option>`).join('')}</select><label class="lbl">Вторая сторона (ФИО / организация)</label><input class="input" id="dc-p"><label class="lbl">Предмет / должность</label><input class="input" id="dc-t"><label class="lbl">Сумма, ₽</label><input class="input" id="dc-s" type="number" value="0"><label class="lbl">Дата</label><input class="input" id="dc-d" type="date" value="${dAgo(0)}"><div class="row"><button class="btn pri" onclick="docCreate()">📄 Создать</button></div>`)}
function docCreate(){if(!val('dc-p')){toast('Укажите вторую сторону',true);return}const kind=val('dc-k')==='Акт'?'Акт':'Договор';const rec={id:uid(),owner_id:meId(),kind,type:val('dc-t')||val('dc-k'),person:val('dc-p'),no:'Д-'+String(Date.now()).slice(-6),date:val('dc-d'),status:'Черновик',sum:num('dc-s'),tpl:val('dc-k'),body:'',created_at:now()};rec.body=DOCTPL[rec.tpl]({no:rec.no,person:rec.person,type:rec.type,date:rec.date,sum:rec.sum,city:G.profile.city},G.profile);putRec('u_documents',rec);closeDrawer();docView(rec.id);toast('Документ создан')}
function docView(id){const d=find('u_documents',id);openDrawer(`<h3>${esc(d.kind)} № ${esc(d.no)}</h3><textarea class="input" id="dv-b" style="min-height:280px;font-family:monospace;font-size:11.5px">${esc(d.body||'')}</textarea><div class="row"><button class="btn sm pri" onclick="putRec('u_documents',{id:'${id}',body:val('dv-b')});toast('Сохранено')">💾</button><button class="btn sm gh" onclick="copyTxt('dv-b')">📋</button><button class="btn sm gh" onclick="downloadTxt('dv-b','${esc(d.no)}.txt')">⬇️</button>${d.status!=='Подписан'?`<button class="btn sm pri" onclick="docSign('${id}')">✍️ Подписать</button>`:''}</div>`)}
function docSign(id){const code=String(Math.floor(1000+Math.random()*9000));openDrawer(`<h3>✍️ Подписание ПЭП</h3><div class="note">Код подтверждения отправлен на ${esc(G.profile.phone||'ваш телефон')} (демо): <b style="color:var(--ice);font-size:18px">${code}</b></div><label class="lbl">Введите код</label><input class="input" id="sg-c" inputmode="numeric"><div class="row"><button class="btn pri" onclick="docSignCheck('${id}','${code}')">Подписать</button></div>`)}
function docSignCheck(id,code){if(val('sg-c')!==code){toast('Неверный код',true);return}putRec('u_documents',{id,status:'Подписан'});closeDrawer();toast('Документ подписан ПЭП')}
function mReports(){const y=new Date().getFullYear();const cal=[['ЕФС-1 (приём/увольнение)','до 25 числа следующего месяца',dAgo(-8)],['Персонифицированные сведения','до 25 числа',dAgo(-5)],['РСВ','до 25 числа после квартала',dAgo(-40)],['6-НДФЛ','до 25 числа после квартала',dAgo(-40)],['Уведомление НПД (самозанятые)','чек в «Мой налог» при расчёте',dAgo(0)],['УСН декларация ИП','до 25 апреля',y+'-04-25']];const done=JSON.parse(localStorage.getItem('rep_done')||'[]');return `<div class="card"><h3>${ic('cal')} Отчётность ИФНС и СФР</h3><div class="note">Календарь обязательств. Данные для форм берутся из ваших сделок, актов и поступлений; экспорт CSV — для 1С и операторов ЭДО.</div>${cal.map(([t,s,d],i)=>`<div class="item"><div class="row" style="margin:0"><input class="cb" type="checkbox" ${done.includes(i)?'checked':''} onclick="repToggle(${i},this.checked)"><div style="flex:1"><div class="t" style="${done.includes(i)?'text-decoration:line-through;opacity:.6':''}">${esc(t)}</div><div class="s">${esc(s)} · ориентир: ${fdate(d)}</div></div></div></div>`).join('')}<div class="row"><button class="btn sm pri" onclick="exportCSV()">⬇️ CSV доходов</button><button class="btn sm gh" onclick="exportDealsCSV()">⬇️ CSV сделок и актов</button></div></div>`}
function repToggle(i,on){const d=JSON.parse(localStorage.getItem('rep_done')||'[]');const j=d.indexOf(i);if(on&&j<0)d.push(i);if(!on&&j>=0)d.splice(j,1);localStorage.setItem('rep_done',JSON.stringify(d));render()}
function exportDealsCSV(){const ds=rows('u_deals').filter(d=>d.employer_id===meId()||d.worker_id===meId());const csv='id;тип;название;исполнитель;заказчик;сумма;статус;закрыта\n'+ds.map(d=>[d.id,d.kind,d.title,d.worker_name,d.employer_name,d.rate,d.status,d.closed_at||''].join(';')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sibiryak-sdelki.csv';a.click();toast('CSV сделок скачан')}
const COURSES=[['Водитель погрузчика','УЦ «Профи»',160,9000,'Склад'],['Сварщик НАКС','УЦ «Профи»',240,18000,'Строительство и ремонт'],['Оператор ЧПУ','УЦ «Техно»',200,15000,'Склад'],['Курьер на авто','Сибиряк Навык',24,1500,'Курьерская доставка'],['Комплектовщик','Склад «Южный»',80,4500,'Склад'],['Охрана труда','УЦ «Профи»',40,2500,'Другое'],['Первая помощь','Красный Крест',16,0,'Медицина и здоровье'],['Excel для работы','Онлайн',24,0,'Другое']];
function mCourses(){const en=mine('u_enrollments');const demand=c=>rows('u_shifts').filter(s=>s.status==='open'&&s.category===c).length+rows('u_requests').filter(r=>r.status==='open'&&r.category===c).length;return `<div class="card"><h3>${ic('book')} Обучение под реальный спрос</h3><div class="note">Курсы связаны с открытыми сменами и заявками: учитесь там, где есть заработок.</div></div>${COURSES.map(([t,o,h,p,c])=>{const e=en.find(x=>x.course===t);const d=demand(c);return `<div class="item reveal"><div class="row" style="margin:0"><div style="flex:1"><div class="t">${esc(t)}</div><div class="s">${esc(o)} · ${h} ч · ${p?money(p):'бесплатно'} · спрос рядом: <b style="color:${d?'var(--pine)':'var(--faint)'}">${d}</b></div></div>${e?`<span class="pill ${e.status==='Завершён'?'p-ok':'p-wait'}">${esc(e.status)}</span>${e.status!=='Завершён'?`<button class="btn sm gh" onclick="enSet('${e.id}','${e.status==='Записан'?'В процессе':'Завершён'}')">${e.status==='Записан'?'Начать':'Завершить'}</button>`:''}`:`<button class="btn sm pri" onclick="enroll('${esc(t)}','${esc(o)}')">Записаться</button>`}</div></div>`}).join('')}`}
function enroll(t,o){const e={id:uid(),owner_id:meId(),course:t,org:o,status:'Записан',created_at:now()};G.cache.u_enrollments.unshift(e);mirror();render();persist('u_enrollments',e,'ins').catch(()=>{});toast('Записаны на курс: '+t)}
function enSet(id,st){putRec('u_enrollments',{id,status:st});if(st==='Завершён'){G.profile.skills=(G.profile.skills?G.profile.skills+', ':'')+find('u_enrollments',id).course;persist('u_profiles',{id:G.profile.id,skills:G.profile.skills},'upd').catch(()=>{});toast('Курс завершён — навык добавлен в профиль')}else toast('Статус: '+st)}
function mLegal(){const ds=rows('u_deals').filter(d=>d.worker_id===meId()||d.employer_id===meId());return `<div class="card"><h3>${ic('law')} Защита и право</h3><div class="note">Платформа собирает претензию, жалобу в ГИТ или иск из данных сделки: стороны, суммы, хронология, чек-ины. Вам остаётся отправить.</div></div>${ds.map(d=>`<div class="item"><div class="row" style="margin:0"><div style="flex:1"><div class="t">${esc(d.title)}</div><div class="s">${esc(d.employer_name)} ↔ ${esc(d.worker_name)} · ${money(d.rate)} · ${DST[d.status]}</div></div><button class="btn sm gh" onclick="complaint('${d.id}')">📄 Претензия</button><button class="btn sm gh" onclick="gitComplaint('${d.id}')">⚖️ Жалоба в ГИТ</button></div></div>`).join('')||'<div class="empty">Сделок нет.</div>'}<div class="card"><h3>Партнёры правовой помощи</h3>${rows('u_partners').filter(p=>p.category==='law'&&p.status==='verified').map(p=>`<div class="item"><div class="t">${esc(p.name)}</div><div class="s">${esc(p.about)}</div><div class="row"><button class="btn sm pri" onclick="leadForm('${p.id}','${esc(p.services[0].title)}',${+p.services[0].price||0})">Заказать консультацию</button></div></div>`).join('')||'<div class="note">Юрбюро появятся после проверки партнёров.</div>'}</div>`}
function gitComplaint(id){const d=find('u_deals',id);const txt=`В Государственную инспекцию труда\nот ${meName()}, ${G.profile.city}\n\nЖАЛОБА\nна нарушение трудовых прав при исполнении «${d.title}».\nЗаказчик/работодатель: ${d.employer_name}.\nСумма обязательств: ${d.rate} руб.\nФакты: ${(d.events||[]).map(e=>e.text).join('; ')}.\nПрошу провести проверку, обязать выплатить задолженность и компенсацию по ст. 236 ТК РФ.\nПриложения: история сделки, переписка, акт, чек-ин.\n${new Date().toLocaleDateString('ru-RU')} · ${meName()}`;openDrawer(`<h3>⚖️ Жалоба в ГИТ</h3><textarea class="input" id="git" style="min-height:260px;font-family:monospace;font-size:11.5px">${esc(txt)}</textarea><div class="row"><button class="btn sm pri" onclick="copyTxt('git')">📋</button><button class="btn sm gh" onclick="downloadTxt('git','zhaloba-git.txt')">⬇️</button></div>`)}
function mPassport(){const closed=rows('u_deals').filter(d=>d.worker_id===meId()&&d.status==='closed');const rv=rows('u_reviews').filter(r=>r.target_id===meId());const stars=rv.length?(rv.reduce((a,r)=>a+r.stars,0)/rv.length).toFixed(1):'—';const txt=`РАБОЧИЙ ПАСПОРТ · СИБИРЯК\n${meName()} · ${G.profile.city}\n\nЗакрытых сделок: ${closed.length}\nЗаработано: ${money(closed.reduce((a,d)=>a+d.rate,0))}\nРейтинг: ${stars}★ (${rv.length} отзывов)\nНавыки: ${G.profile.skills||'—'}\nОпыт: ${G.profile.exp_years||0} лет\nКурсы: ${mine('u_enrollments').filter(e=>e.status==='Завершён').map(e=>e.course).join(', ')||'—'}\n\nСделки:\n${closed.map(d=>'- '+d.title+' · '+money(d.rate)+' · '+String(d.closed_at||'').slice(0,10)).join('\n')||'- нет'}\n\nОтзывы:\n${rv.map(r=>'- '+r.stars+'★ '+r.text).join('\n')||'- нет'}\n\nПаспорт переносим между городами и работодателями.\n${new Date().toLocaleString('ru-RU')}`;return `<div class="card"><h3>${ic('pass')} Рабочий паспорт</h3><div class="note">Вся ваша история в одном переносимом документе: сделки, рейтинг, навыки, курсы.</div><textarea class="input" id="pp" style="min-height:300px;font-family:monospace;font-size:11.5px">${esc(txt)}</textarea><div class="row"><button class="btn sm pri" onclick="copyTxt('pp')">📋 Копировать</button><button class="btn sm gh" onclick="downloadTxt('pp','passport.txt')">⬇️ Скачать</button></div></div>`}
function copyTxt(id){const e=$(id);if(navigator.clipboard)navigator.clipboard.writeText(e.value).then(()=>toast('Скопировано')).catch(()=>{e.select();document.execCommand('copy');toast('Скопировано')});else{e.select();document.execCommand('copy');toast('Скопировано')}}
function downloadTxt(id,name){const e=$(id);const b=new Blob([e.value],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Файл скачан')}
async function avatarUpload(input){const f=input.files[0];if(!f)return;const dataUrl=await new Promise(res=>{const img=new Image();const r=new FileReader();r.onload=()=>{img.onload=()=>{const c=document.createElement('canvas');const s=Math.min(1,256/Math.max(img.width,img.height));c.width=img.width*s;c.height=img.height*s;c.getContext('2d').drawImage(img,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.85))};img.src=r.result};r.readAsDataURL(f)});const url=await SBup('profile/'+meId()+'.jpg',f);G.profile.avatar_url=url||dataUrl;putRec('u_profiles',{id:G.profile.id,avatar_url:G.profile.avatar_url});paintAvatar();toast(url?'Аватар загружен в хранилище':'Аватар сохранён локально')}
function setRole(v){G.profile.role=v;putRec('u_profiles',{id:G.profile.id,role:v});toast('Режим кабинета: '+v)}
function mSettings(){const p=G.profile;return `<div class="card"><h3>${ic('set')} Профиль</h3><div class="row" style="margin-top:0"><div class="avprev">${p.avatar_url?`<img src="${esc(p.avatar_url)}">`:esc((p.name||'?')[0])}</div><div style="flex:1"><label class="lbl">Аватар (фото с телефона или селфи)</label><input class="input" type="file" accept="image/*" onchange="avatarUpload(this)">${p.avatar_url?`<button class="btn sm dgr" onclick="G.profile.avatar_url='';putRec('u_profiles',{id:G.profile.id,avatar_url:''});paintAvatar()">Убрать фото</button>`:''}</div></div><label class="lbl">Имя / название</label><input class="input" id="st-n" value="${esc(p.name)}"><label class="lbl">Город</label><input class="input" id="st-c" value="${esc(p.city)}"><label class="lbl">Телефон</label><input class="input" id="st-p" value="${esc(p.phone||'')}"><label class="lbl">Навыки через запятую</label><input class="input" id="st-sk" value="${esc(p.skills||'')}"><label class="lbl">Опыт, лет</label><input class="input" id="st-e" type="number" value="${p.exp_years||0}"><label class="lbl">Зарплата от, ₽</label><input class="input" id="st-s" type="number" value="${p.salary_min||0}"><label class="lbl">Радиус поиска: ${p.radius_km||60} км</label><input type="range" min="10" max="300" step="10" value="${p.radius_km||60}" style="width:100%;accent-color:var(--ice)" oninput="G.profile.radius_km=+this.value;this.previousElementSibling.textContent='Радиус поиска: '+this.value+' км'">${p.role==='company'?`<label class="lbl">Название компании</label><input class="input" id="st-co" value="${esc(p.company_name||'')}"><label class="lbl">ИНН</label><input class="input" id="st-inn" value="${esc(p.inn||'')}">`:''}<label class="lbl">Режим кабинета</label><select class="input" onchange="setRole(this.value)">${[['seeker','Соискатель / исполнитель'],['company','Работодатель / заказчик'],['partner','Партнёр услуг']].map(([v,t])=>`<option value="${v}" ${p.role===v?'selected':''}>${t}</option>`).join('')}</select><div class="row"><button class="btn pri" onclick="profSave()">💾 Сохранить профиль</button><button class="btn gh" onclick="logout()">🚪 Выйти</button></div></div><div class="card"><h3>${ic('db')} База данных</h3><div class="note">Режим: <b>${G.mode==='cloud'?'облако Supabase':'демо (локально)'}</b>. ${G.mode==='cloud'?'Все записи привязаны к вашему аккаунту (auth.uid()), политики RLS изолируют данные.':'Данные только в этом браузере.'}</div><div class="row"><button class="btn sm pri" onclick="openSetup()">📋 SQL схемы</button><button class="btn sm gh" onclick="testConn()">🔌 Проверить связь</button>${G.mode==='cloud'?`<button class="btn sm gh" onclick="cloudLoad().then(m=>{G.setupOk=m.length===0;render();toast(m.length?'Нет таблиц: '+m.length:'База загружена')})">⬇️ Перезагрузить</button>`:''}</div><label class="lbl">Project URL</label><input class="input" id="sb-u" value="${esc(G.sb.url)}"><label class="lbl">Publishable / anon key</label><input class="input" id="sb-k" value="${esc(G.sb.key)}"><div class="row"><button class="btn sm gh" onclick="G.sb={url:val('sb-u'),key:val('sb-k')};localStorage.setItem('sb_cfg',JSON.stringify(G.sb));toast('Реквизиты сохранены')">💾 Реквизиты</button></div></div>`}
function profSave(){const p=G.profile;Object.assign(p,{name:val('st-n')||p.name,city:val('st-c')||p.city,phone:val('st-p'),skills:val('st-sk'),exp_years:num('st-e'),salary_min:num('st-s')});if(p.role==='company'){p.company_name=val('st-co');p.inn=val('st-inn')}mirror();render();persist('u_profiles',p,'upd').catch(()=>{});toast('Профиль сохранён в базе')}
async function testConn(){try{await authFetch('/rest/v1/',{headers:{Authorization:'Bearer '+(G.session?G.session.access_token:G.sb.key)}});toast('Связь с Supabase есть')}catch(e){toast('Связь: '+e.message,true)}}
const SQL=`-- СИБИРЯК · схема, формируемая регистрациями (Supabase → SQL Editor → Run)
create extension if not exists pgcrypto;
create table if not exists u_profiles(id uuid primary key references auth.users(id) on delete cascade, owner_id uuid, role text default 'seeker', name text, city text, phone text, skills text, exp_years int default 0, salary_min int default 0, availability text default 'free', radius_km int default 60, company_name text, inn text, avatar_url text, created_at timestamptz default now());
alter table u_profiles add column if not exists avatar_url text;
create table if not exists u_resumes(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, title text, city text, exp_years int default 0, skills text, about text, sort int default 0, created_at timestamptz default now());
create table if not exists u_vacancies(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, company text, title text, city text, salary int default 0, skills text, exp_min int default 0, status text default 'open', descr text, sort int default 0, created_at timestamptz default now());
create table if not exists u_shifts(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, employer_name text, title text, category text, city text, date date, start text, end text, rate int default 0, count int default 1, taken int default 0, req text, status text default 'open', cycle text, descr text, sort int default 0, created_at timestamptz default now());
create table if not exists u_requests(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, author_name text, author_role text, kind text default 'service', category text, title text, city text, budget int default 0, deadline date, descr text, status text default 'open', sort int default 0, created_at timestamptz default now());
create table if not exists u_bids(id uuid primary key default gen_random_uuid(), request_id uuid, owner_id uuid references auth.users(id) on delete cascade, author_name text, price int default 0, comment text, created_at timestamptz default now());
create table if not exists u_deals(id uuid primary key default gen_random_uuid(), owner_id uuid, kind text, shift_id uuid, request_id uuid, worker_id uuid, employer_id uuid, worker_name text, employer_name text, title text, city text, rate int default 0, status text default 'new', deadline date, checkin_at timestamptz, checkout_at timestamptz, closed_at timestamptz, meeting_url text, events jsonb default '[]', created_at timestamptz default now());
create table if not exists u_messages(id uuid primary key default gen_random_uuid(), deal_id uuid, lead_id uuid, owner_id uuid references auth.users(id) on delete cascade, author_name text, body text, read boolean default false, created_at timestamptz default now());
create table if not exists u_interviews(id uuid primary key default gen_random_uuid(), owner_id uuid, candidate_id uuid, candidate_name text, vacancy_title text, dt timestamptz, status text default 'scheduled', meeting_url text, created_at timestamptz default now());
create table if not exists u_reviews(id uuid primary key default gen_random_uuid(), owner_id uuid, target_id uuid, target_name text, stars int, text text, deal_id uuid, created_at timestamptz default now());
create table if not exists u_partners(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, category text, name text, org text, inn text, ogrn text, license text, city text, radius int default 60, phone text, site text, about text, plan text default 'free', status text default 'draft', consent boolean default false, docs jsonb default '[]', services jsonb default '[]', reject jsonb default '[]', sort int default 0, created_at timestamptz default now());
create table if not exists u_leads(id uuid primary key default gen_random_uuid(), partner_id uuid, owner_id uuid, service text, client text, phone text, budget int default 0, comment text, status text default 'new', msgs jsonb default '[]', created_at timestamptz default now());
create table if not exists u_incomes(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, date date, cat text, amount int default 0, note text, created_at timestamptz default now());
create table if not exists u_documents(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, kind text, type text, person text, no text, date date, status text default 'Черновик', sum int default 0, tpl text, body text, created_at timestamptz default now());
create table if not exists u_notifications(id uuid primary key default gen_random_uuid(), owner_id uuid, text text, read boolean default false, created_at timestamptz default now());
create table if not exists u_family(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, goal_title text, target int default 50000, saved int default 0, percent int default 10, members jsonb default '[]', created_at timestamptz default now());
create table if not exists u_enrollments(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, course text, org text, status text default 'Записан', created_at timestamptz default now());
create table if not exists u_views(id uuid primary key default gen_random_uuid(), owner_id uuid references auth.users(id) on delete cascade, ctx text, name text, state jsonb, created_at timestamptz default now());
create or replace function public.u_on_signup() returns trigger language plpgsql security definer set search_path=public as $$
begin
  insert into public.u_profiles(id,owner_id,role,name,city)
  values(new.id,new.id,coalesce(new.raw_user_meta_data->>'role','seeker'),coalesce(new.raw_user_meta_data->>'name','Пользователь'),coalesce(new.raw_user_meta_data->>'city','Барнаул'))
  on conflict (id) do nothing;
  return new;
end $$;
drop trigger if exists u_on_signup on auth.users;
create trigger u_on_signup after insert on auth.users for each row execute function public.u_on_signup();
do $$ declare t text;
begin
  foreach t in array array['u_profiles','u_resumes','u_vacancies','u_shifts','u_requests','u_bids','u_partners','u_incomes','u_documents','u_family','u_enrollments','u_views']
  loop
    execute format('alter table public.%I enable row level security',t);
    execute format('drop policy if exists own_sel on public.%I',t);
    execute format('drop policy if exists own_ins on public.%I',t);
    execute format('drop policy if exists own_upd on public.%I',t);
    execute format('drop policy if exists own_del on public.%I',t);
    execute format('create policy own_sel on public.%I for select using (owner_id = auth.uid())',t);
    execute format('create policy own_ins on public.%I for insert with check (owner_id = auth.uid())',t);
    execute format('create policy own_upd on public.%I for update using (owner_id = auth.uid())',t);
    execute format('create policy own_del on public.%I for delete using (owner_id = auth.uid())',t);
  end loop;
end $$;
do $$ declare t text;
begin
  foreach t in array array['u_profiles','u_shifts','u_requests','u_vacancies','u_partners','u_reviews','u_bids']
  loop
    execute format('drop policy if exists mkt_sel on public.%I',t);
    execute format('create policy mkt_sel on public.%I for select to authenticated using (true)',t);
  end loop;
end $$;
alter table u_reviews enable row level security;
drop policy if exists own_ins on u_reviews; drop policy if exists own_upd on u_reviews; drop policy if exists own_del on u_reviews;
create policy own_ins on u_reviews for insert with check (owner_id = auth.uid());
create policy own_upd on u_reviews for update using (owner_id = auth.uid());
create policy own_del on u_reviews for delete using (owner_id = auth.uid());
drop policy if exists shift_take on u_shifts;
create policy shift_take on u_shifts for update to authenticated using (status in ('open','full')) with check (taken >= 0 and taken <= count);
drop policy if exists req_take on u_requests;
create policy req_take on u_requests for update to authenticated using (status = 'open') with check (status in ('open','taken','closed'));
alter table u_deals enable row level security;
drop policy if exists deal_sel on u_deals; drop policy if exists deal_ins on u_deals; drop policy if exists deal_upd on u_deals;
create policy deal_sel on u_deals for select to authenticated using (worker_id = auth.uid() or employer_id = auth.uid());
create policy deal_ins on u_deals for insert to authenticated with check (worker_id = auth.uid() or employer_id = auth.uid());
create policy deal_upd on u_deals for update to authenticated using (worker_id = auth.uid() or employer_id = auth.uid());
alter table u_messages enable row level security;
drop policy if exists msg_sel on u_messages; drop policy if exists msg_ins on u_messages; drop policy if exists msg_upd on u_messages;
create policy msg_sel on u_messages for select to authenticated using (exists(select 1 from u_deals d where d.id=deal_id and (d.worker_id=auth.uid() or d.employer_id=auth.uid())));
create policy msg_ins on u_messages for insert to authenticated with check (owner_id=auth.uid() and exists(select 1 from u_deals d where d.id=deal_id and (d.worker_id=auth.uid() or d.employer_id=auth.uid())));
create policy msg_upd on u_messages for update to authenticated using (exists(select 1 from u_deals d where d.id=deal_id and (d.worker_id=auth.uid() or d.employer_id=auth.uid())));
alter table u_interviews enable row level security;
drop policy if exists int_sel on u_interviews; drop policy if exists int_ins on u_interviews; drop policy if exists int_upd on u_interviews;
create policy int_sel on u_interviews for select to authenticated using (owner_id=auth.uid() or candidate_id=auth.uid());
create policy int_ins on u_interviews for insert to authenticated with check (owner_id=auth.uid());
create policy int_upd on u_interviews for update to authenticated using (owner_id=auth.uid() or candidate_id=auth.uid());
alter table u_leads enable row level security;
drop policy if exists lead_sel on u_leads; drop policy if exists lead_ins on u_leads; drop policy if exists lead_upd on u_leads; drop policy if exists lead_del on u_leads;
create policy lead_sel on u_leads for select to authenticated using (owner_id=auth.uid() or exists(select 1 from u_partners p where p.id=partner_id and p.owner_id=auth.uid()));
create policy lead_ins on u_leads for insert to authenticated with check (owner_id=auth.uid());
create policy lead_upd on u_leads for update to authenticated using (owner_id=auth.uid() or exists(select 1 from u_partners p where p.id=partner_id and p.owner_id=auth.uid()));
create policy lead_del on u_leads for delete to authenticated using (owner_id=auth.uid());
alter table u_notifications enable row level security;
drop policy if exists nt_sel on u_notifications; drop policy if exists nt_ins on u_notifications; drop policy if exists nt_upd on u_notifications;
create policy nt_sel on u_notifications for select to authenticated using (owner_id=auth.uid());
create policy nt_ins on u_notifications for insert to authenticated with check (true);
create policy nt_upd on u_notifications for update to authenticated using (owner_id=auth.uid());
create index if not exists u_shifts_owner on u_shifts(owner_id);
create index if not exists u_requests_owner on u_requests(owner_id);
create index if not exists u_deals_worker on u_deals(worker_id);
create index if not exists u_deals_employer on u_deals(employer_id);
create index if not exists u_messages_deal on u_messages(deal_id);
create index if not exists u_leads_partner on u_leads(partner_id);`;
function openSetup(missing){openDrawer(`<h3>🗄️ SQL схемы: база из регистраций</h3><div class="note">Вставьте в Supabase → SQL Editor → New query → Run. Триггер создаёт профиль при каждой регистрации; RLS отдаёт каждому только его данные, рынок читается всеми вошедшими.${missing&&missing.length?' Не хватает таблиц: '+missing.length+'.':''}</div><textarea class="input" id="sqlbox" style="min-height:320px;font-family:monospace;font-size:10.5px">${esc(SQL)}</textarea><div class="row"><button class="btn pri" onclick="copyTxt('sqlbox')">📋 Копировать SQL</button><button class="btn gh" onclick="downloadTxt('sqlbox','sibiryak-schema.sql')">⬇️ Файл</button></div><div class="note" style="margin-top:8px">После выполнения: зарегистрируйтесь в приложении — профиль и данные появятся в базе автоматически.</div>`)}
window.addEventListener('resize',()=>{$('nav-toggle').style.display=window.innerWidth<=900&&G.profile?'':'none'});
(function init(){
  G.sb=sbCfg();
  const s=localStorage.getItem('sb_session');
  if(s){try{G.session=JSON.parse(s);G.user=G.session.user;G.mode='cloud';
    refreshSession().then(()=>cloudLoad()).then(missing=>{G.setupOk=missing.length===0;G.profile=rows('u_profiles').find(p=>p.id===G.user.id)||null;if(!G.profile){const meta=G.user.user_metadata||{};G.profile={id:G.user.id,owner_id:G.user.id,role:meta.role||'seeker',name:meta.name||'Пользователь',city:meta.city||'Барнаул',phone:'',skills:'',exp_years:0,salary_min:0,availability:'free',radius_km:60,company_name:'',inn:'',avatar_url:'',created_at:now()};G.cache.u_profiles.unshift(G.profile);persist('u_profiles',G.profile,'ins').catch(()=>{})}enterApp()}).catch(()=>{localStorage.removeItem('sb_session');G.session=null;G.mode='demo';loadMirror();if(!rows('u_profiles').length)seedDemo();renderAuth('landing')});
    return}catch(e){}}
  loadMirror();if(!rows('u_profiles').length)seedDemo();
  renderAuth('landing');
})();